import 'dart:convert';\nimport 'dart:io';\nimport 'package:path/path.dart' as path;\n\n/// Handles JSON parsing, validation, transformation, and file I/O.\nclass JsonProcessor {\n  /// Parses a JSON string into a Map or List.\n  /// Returns `null` if parsing fails.\n  Map<String, dynamic>? parseJson(String jsonString) {\n    try {\n      final dynamic result = jsonDecode(jsonString);\n      if (result is Map<String, dynamic>) {\n        return result;\n      }\n      return null;\n    } catch (e) {\n      print('JSON Parse Error: \\$(e.toString())');\n      return null;\n    }\n  }\n\n  /// Validates that a value is of the expected type.\n  /// Supported types: 'string', 'int', 'double', 'bool', 'list', 'map'.\n  bool validateField(dynamic value, String fieldName, String expectedType) {\n    switch (expectedType.toLowerCase()) {\n      case 'string':\n        return value is String;\n      case 'int':\n        return value is int;\n      case 'double':\n        return value is double || value is int;\n      case 'bool':\n        return value is bool;\n      case 'list':\n        return value is List;\n      case 'map':\n        return value is Map;\n      default:\n        return false;\n    }\n  }\n\n  /// Applies a transformation function to each item in a list.\n  /// If the function returns `null`, the item is filtered out.\n  List<T> transform<T>(List<dynamic> items, T? Function(dynamic item) transformer) {\n    final result = <T>[];\n    for (final item in items) {\n      final transformed = transformer(item);\n      if (transformed != null) {\n        result.add(transformed);\n      }\n    }\n    return result;\n  }\n\n  /// Saves a list of items as a JSON file.\n  /// Creates parent directories if they don't exist.\n  Future<void> saveToJson(List<dynamic> items, String filePath) async {\n    try {\n      final file = File(filePath);\n      await file.parent.create(recursive: true);\n      await file.writeAsString(const JsonEncoder.withIndent('  ').convert(items));\n      print('Saved JSON to: \\${path.basename(filePath)}');\n    } catch (e) {\n      print('JSON Save Error: \\$(e.toString())');\n    }\n  }\n}\n
